#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>

extern "C" {
#include "cJSON.h"
}
#include "lodepng.h"

static const int IMG = 28;
static const int IN_DIM = 784;
static const int HID = 16;
static const int OUT = 10;

static bool read_file(const char *path, std::string &data) {
    FILE *f = fopen(path, "rb");
    if (!f) return false;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n < 0) { fclose(f); return false; }
    data.resize((size_t)n);
    size_t got = fread(&data[0], 1, (size_t)n, f);
    fclose(f);
    return got == (size_t)n;
}

static bool load_vector(const cJSON *obj, const char *name, std::vector<float> &v, int n) {
    const cJSON *arr = cJSON_GetObjectItemCaseSensitive(obj, name);
    if (!cJSON_IsArray(arr)) return false;
    int len = cJSON_GetArraySize(arr);
    if (len != n) return false;
    v.resize(n);
    for (int i = 0; i < n; ++i) {
        const cJSON *it = cJSON_GetArrayItem(arr, i);
        if (!cJSON_IsNumber(it)) return false;
        v[i] = (float)it->valuedouble;
    }
    return true;
}

static bool load_matrix(const cJSON *obj, const char *name, std::vector<float> &v, int rows, int cols) {
    const cJSON *arr = cJSON_GetObjectItemCaseSensitive(obj, name);
    if (!cJSON_IsArray(arr) || cJSON_GetArraySize(arr) != rows) return false;
    v.resize((size_t)rows * cols);
    for (int r = 0; r < rows; ++r) {
        const cJSON *row = cJSON_GetArrayItem(arr, r);
        if (!cJSON_IsArray(row) || cJSON_GetArraySize(row) != cols) return false;
        for (int c = 0; c < cols; ++c) {
            const cJSON *it = cJSON_GetArrayItem(row, c);
            if (!cJSON_IsNumber(it)) return false;
            v[(size_t)r * cols + c] = (float)it->valuedouble;
        }
    }
    return true;
}

// Sample the RGBA image at a normalized coordinate; luminance in [0,1].
static float sample_gray(const std::vector<unsigned char> &rgba, unsigned w, unsigned h,
                         double sx, double sy) {
    int x0 = (int)floor(sx), y0 = (int)floor(sy);
    if (x0 < 0) x0 = 0;
    if (y0 < 0) y0 = 0;
    if (x0 >= (int)w) x0 = (int)w - 1;
    if (y0 >= (int)h) y0 = (int)h - 1;
    size_t idx = ((size_t)y0 * w + x0) * 4;
    float r = rgba[idx + 0], g = rgba[idx + 1], b = rgba[idx + 2], a = rgba[idx + 3];
    float lum = (0.299f * r + 0.587f * g + 0.114f * b) / 255.0f;
    return lum * (a / 255.0f);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    std::string json;
    if (!read_file(argv[1], json)) {
        fprintf(stderr, "error: cannot read weights file: %s\n", argv[1]);
        return 1;
    }
    cJSON *root = cJSON_ParseWithLength(json.c_str(), json.size());
    if (!root) {
        fprintf(stderr, "error: invalid JSON in %s\n", argv[1]);
        return 1;
    }

    std::vector<float> w1, b1, w2, b2, w3, b3;
    bool ok = load_matrix(root, "input_layer.weight", w1, HID, IN_DIM) &&
              load_vector(root, "input_layer.bias", b1, HID) &&
              load_matrix(root, "hidden_layer.weight", w2, HID, HID) &&
              load_vector(root, "hidden_layer.bias", b2, HID) &&
              load_matrix(root, "output_layer.weight", w3, OUT, HID) &&
              load_vector(root, "output_layer.bias", b3, OUT);
    cJSON_Delete(root);
    if (!ok) {
        fprintf(stderr, "error: weights JSON has unexpected structure\n");
        return 1;
    }

    std::vector<unsigned char> rgba;
    unsigned w = 0, h = 0;
    unsigned err = lodepng::decode(rgba, w, h, argv[2]);
    if (err || w == 0 || h == 0) {
        fprintf(stderr, "error: cannot decode image %s: %s\n", argv[2], lodepng_error_text(err));
        return 1;
    }

    // Convert to 28x28 grayscale, scaled to [-1, 1] (matching training transform).
    std::vector<float> x(IN_DIM);
    for (int oy = 0; oy < IMG; ++oy) {
        for (int ox = 0; ox < IMG; ++ox) {
            double sx = ((ox + 0.5) * (double)w / IMG) - 0.5;
            double sy = ((oy + 0.5) * (double)h / IMG) - 0.5;
            float g = sample_gray(rgba, w, h, sx, sy);
            x[oy * IMG + ox] = g * 2.0f - 1.0f;
        }
    }

    std::vector<float> h1((size_t)HID), h2((size_t)HID), out((size_t)OUT);
    for (int j = 0; j < HID; ++j) {
        float sum = b1[j];
        const float *row = &w1[(size_t)j * IN_DIM];
        for (int i = 0; i < IN_DIM; ++i) sum += row[i] * x[i];
        h1[j] = sum > 0.0f ? sum : 0.0f;
    }
    for (int j = 0; j < HID; ++j) {
        float sum = b2[j];
        const float *row = &w2[(size_t)j * HID];
        for (int i = 0; i < HID; ++i) sum += row[i] * h1[i];
        h2[j] = sum > 0.0f ? sum : 0.0f;
    }
    int best = 0;
    for (int j = 0; j < OUT; ++j) {
        float sum = b3[j];
        const float *row = &w3[(size_t)j * HID];
        for (int i = 0; i < HID; ++i) sum += row[i] * h2[i];
        out[j] = sum;
        if (sum > out[best]) best = j;
    }

    printf("%d\n", best);
    return 0;
}

